         margin: 24px 0 0;
         color: var(--muted);
         font-size: 1.1rem;
         line-height: 1.7;
       }

       .cat-card {
         position: relative;
         overflow: hidden;
         min-height: 320px;
         border: 1px solid rgba(255, 255, 255, 0.82);
         border-radius: 34px;
         background:
           linear-gradient(145deg, rgba(255, 255, 255, 0.9), rgba(246, 248, 255, 0.74)),
           radial-gradient(circle at 75% 15%, rgba(108, 92, 231, 0.28), transparent 15rem);
         box-shadow: var(--shadow);
       }

       .cat-card::before,
       .cat-card::after {
         content: "";
         position: absolute;
         border-radius: 999px;
         background: rgba(108, 92, 231, 0.1);
       }

       .cat-card::before {
         width: 170px;
         height: 170px;
         right: -52px;
         top: -42px;
       }

       .cat-card::after {
         width: 210px;
         height: 210px;
         left: -62px;
         bottom: -90px;
       }

       .cat-illustration {
         position: absolute;
         inset: 42px;
         display: grid;
         place-items: center;
         font-size: 9rem;
         filter: drop-shadow(0 20px 30px rgba(56, 65, 96, 0.12));
       }

       .stats {
         position: absolute;
         right: 22px;
         bottom: 22px;
         left: 22px;
         display: grid;
         grid-template-columns: repeat(3, 1fr);
         gap: 10px;
       }

       .stat {
         padding: 14px;
         border: 1px solid rgba(223, 230, 241, 0.78);
         border-radius: 18px;
         background: rgba(255, 255, 255, 0.78);
         backdrop-filter: blur(14px);
       }

       .stat strong {
         display: block;
         margin-bottom: 3px;
         color: var(--brand-strong);
         font-size: 1.2rem;
       }

       .stat span {
         color: var(--muted);
         font-size: 0.78rem;
         font-weight: 650;
       }

       .faq-panel {
         overflow: hidden;
         border: 1px solid rgba(223, 230, 241, 0.88);
         border-radius: var(--radius);
         background: var(--surface);
         box-shadow: var(--shadow);
         backdrop-filter: blur(20px);
       }

       .faq-toolbar {
         display: flex;
         justify-content: space-between;
         gap: 18px;
         padding: 24px;
         border-bottom: 1px solid var(--line);
       }

       .faq-toolbar h2 {
         margin: 0;
         font-size: 1.25rem;
         letter-spacing: -0.03em;
       }

       .faq-toolbar p {
         margin: 6px 0 0;
         color: var(--muted);
       }

       .pill {
         align-self: start;
         white-space: nowrap;
         padding: 10px 14px;
         border-radius: 999px;
         color: var(--brand-strong);
         background: rgba(108, 92, 231, 0.1);
         font-size: 0.9rem;
         font-weight: 750;
       }

       .faq-list {
         padding: 8px;
       }

       .example {
         border-radius: 18px;
       }

       .example + .example {
         margin-top: 4px;
       }

       .details {
         border-radius: 18px;
         transition: background 180ms ease, box-shadow 180ms ease;
       }

       .details[open] {
         background: #fff;
         box-shadow: inset 0 0 0 1px rgba(223, 230, 241, 0.8);
       }

       summary {
         display: flex;
         align-items: center;
         justify-content: space-between;
         gap: 20px;
         padding: 22px 22px;
         cursor: pointer;
         list-style: none;
         color: var(--text);
         font-weight: 780;
         letter-spacing: -0.015em;
       }

       summary::-webkit-details-marker {
         display: none;
       }

       summary::after {
         content: "+";
         display: grid;
         flex: 0 0 auto;
         place-items: center;
         width: 32px;
         height: 32px;
         border-radius: 50%;
         color: #fff;
         background: var(--brand);
         font-size: 1.35rem;
         line-height: 1;
         transition: transform 180ms ease, background 180ms ease;
       }

       .details[open] summary::after {
         content: "−";
         transform: rotate(180deg);
         background: var(--brand-strong);
       }

       .answer {
         margin: 0;
         padding: 0 22px 24px;
         color: var(--muted);
         font-size: 1rem;
         line-height: 1.75;
       }

')

