        .cat-card {
          min-height: 380px;
        }
      }
    </style>
  </head>
  <body>
    <main id="root"></main>

    <script>
      const faqs = [
        {
          question: "Why do cats knead blankets, pillows, or people?",
          answer:
            "Kneading is a comforting behavior that starts in kittenhood when cats press their paws against their mother while nursing. Adult cats often knead when they feel safe, relaxed, or ready to settle in."
        },
        {
          question: "How much sleep does a healthy cat need?",
          answer:
            "Most cats sleep between 12 and 16 hours a day, and kittens or senior cats may sleep even more. Short bursts of activity between naps are normal because cats are naturally crepuscular, meaning they are often most active around dawn and dusk."
        },
        {
          question: "Why does my cat bring toys or small gifts to me?",
          answer:
            "Cats may bring objects as a form of play, bonding, or instinctive hunting practice. Responding calmly and offering interactive toys can help redirect that energy in a positive way."
        },
        {
          question: "Do indoor cats need enrichment?",
          answer:
            "Yes. Indoor cats benefit from climbing spaces, scratching posts, puzzle feeders, window perches, and daily play. Enrichment helps prevent boredom and supports healthy movement, confidence, and problem solving."
        },
        {
          question: "How often should I groom my cat?",
          answer:
            "Short-haired cats usually need weekly brushing, while long-haired cats may need brushing several times a week. Regular grooming reduces shedding, prevents mats, and gives you a chance to notice skin changes early."
        },
        {
          question: "What does slow blinking mean?",
          answer:
            "A slow blink is often a sign of trust and relaxation. You can slowly blink back to communicate calmly, especially with a cat that is still getting comfortable around you."
        }
      ];

      function Header() {
        return `
          <section class="hero" aria-labelledby="page-title">
            <div>
              <p class="eyebrow">Cat care essentials</p>
              <h1 id="page-title">Frequently asked questions about cats.</h1>
              <p class="intro">
                Quick, practical answers for curious cat people. Expand any question to learn more about feline habits, care, and communication.
              </p>
            </div>
            <aside class="cat-card" aria-label="Cat care highlights">
              <div class="cat-illustration" aria-hidden="true">🐈</div>
              <div class="stats">
                <div class="stat"><strong>12–16h</strong><span>Daily sleep</span></div>
                <div class="stat"><strong>2x</strong><span>Play sessions</span></div>
                <div class="stat"><strong>7+</strong><span>Enrichment ideas</span></div>
              </div>
            </aside>
          </section>
        `;
      }

      function FAQItem({ question, answer }, index) {
        const panelId = `cat-faq-answer-${index + 1}`;
        const buttonId = `cat-faq-question-${index + 1}`;

        return `
          <div class="example">
            <button
              class="question-button"
              id="${buttonId}"
              type="button"
              aria-expanded="false"
              aria-controls="${panelId}"
            >
              ${question}
            </button>
            <div class="details" id="${panelId}" role="region" aria-labelledby="${buttonId}" hidden>
              <p class="answer">${answer}</p>
            </div>
          </div>
        `;
      }

      function FAQList(items) {
        return `
          <section class="faq-panel" aria-labelledby="faq-title">
            <div class="faq-toolbar">
              <div>
                <h2 id="faq-title">Cat FAQ</h2>
                <p>Questions are collapsed by default. Tap or click to expand.</p>
              </div>
              <span class="pill">${items.length} questions</span>
            </div>
            <div class="faq-list">
              ${items.map((item, index) => FAQItem(item, index)).join("")}
            </div>
          </section>
        `;
      }

      function App() {
        return `
          <div class="app-shell">
            ${Header()}
            ${FAQList(faqs)}
          </div>
        `;
      }

      document.querySelector("#root").innerHTML = App();

      document.querySelectorAll(".question-button").forEach((button) => {
        button.addEventListener("click", () => {
          const panel = document.getElementById(button.getAttribute("aria-controls"));
          const isExpanded = button.getAttribute("aria-expanded") === "true";

          button.setAttribute("aria-expanded", String(!isExpanded));
          button.closest(".example").classList.toggle("is-open", !isExpanded);
          panel.hidden = isExpanded;
        });
      });
    </script>
  </body>
</html>
