      .app-shell {
        width: min(1120px, calc(100% - 32px));
        margin: 0 auto;
        padding: 72px 0;
      }

      .hero {
        display: grid;
        grid-template-columns: minmax(0, 1.1fr) minmax(280px, 0.9fr);
        gap: 40px;
        align-items: center;
        margin-bottom: 36px;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        margin: 0 0 16px;
        padding: 8px 12px;
        border: 1px solid rgba(108, 92, 231, 0.18);
        border-radius: 999px;
        color: var(--brand-strong);
        background: rgba(255, 255, 255, 0.72);
        font-size: 0.85rem;
        font-weight: 700;
        letter-spacing: 0.02em;
      }

      h1 {
        margin: 0;
        max-width: 720px;
        font-size: clamp(2.7rem, 7vw, 5.9rem);
        line-height: 0.94;
        letter-spacing: -0.075em;
      }

      .intro {
        max-width: 640px;
        margin: 24px 0 0;
        color: var(--muted);
        font-size: 1.1rem;
        line-height: 1.7;
      }

      .cat-card {
        position: relative;
        overflow: hidden;
        min-height: 320px;
        border: 1px solid rgba(255, 255, 255, 0.82);
        border-radius: 34px;
        background:
          linear-gradient(145deg, rgba(255, 255, 255, 0.9), rgba(246, 248, 255, 0.74)),
          radial-gradient(circle at 75% 15%, rgba(108, 92, 231, 0.28), transparent 15rem);
        box-shadow: var(--shadow);
      }

      .cat-card::before,
      .cat-card::after {
        content: "";
        position: absolute;
        border-radius: 999px;
        background: rgba(108, 92, 231, 0.1);
      }

      .cat-card::before {
        width: 170px;
        height: 170px;
        right: -52px;
        top: -42px;
      }

      .cat-card::after {
        width: 210px;
        height: 210px;
        left: -62px;
        bottom: -90px;
      }

      .cat-illustration {
        position: absolute;
        inset: 42px;
        display: grid;
        place-items: center;
        font-size: 9rem;
        filter: drop-shadow(0 20px 30px rgba(56, 65, 96, 0.12));
      }

      .stats {
        position: absolute;
        right: 22px;
        bottom: 22px;
        left: 22px;
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 10px;
      }

      .stat {
        padding: 14px;
        border: 1px solid rgba(223, 230, 241, 0.78);
        border-radius: 18px;
        background: rgba(255, 255, 255, 0.78);
        backdrop-filter: blur(14px);
      }

      .stat strong {
        display: block;
        margin-bottom: 3px;
        color: var(--brand-strong);
        font-size: 1.2rem;
      }

      .stat span {
        color: var(--muted);
        font-size: 0.78rem;
        font-weight: 650;
      }

      .faq-panel {
        overflow: hidden;
        border: 1px solid rgba(223, 230, 241, 0.88);
        border-radius: var(--radius);
        background: var(--surface);
        box-shadow: var(--shadow);
        backdrop-filter: blur(20px);
      }

      .faq-toolbar {
        display: flex;
        justify-content: space-between;
        gap: 18px;
        padding: 24px;
        border-bottom: 1px solid var(--line);
      }

      .faq-toolbar h2 {
        margin: 0;
        font-size: 1.25rem;
        letter-spacing: -0.03em;
      }

      .faq-toolbar p {
        margin: 6px 0 0;
        color: var(--muted);
      }

      .pill {
        align-self: start;
        white-space: nowrap;
        padding: 10px 14px;
        border-radius: 999px;
        color: var(--brand-strong);
        background: rgba(108, 92, 231, 0.1);
        font-size: 0.9rem;
        font-weight: 750;
      }

      .faq-list {
        padding: 8px;
      }

      .example {
        overflow: hidden;
        border-radius: 18px;
        transition: background 180ms ease, box-shadow 180ms ease;
      }

      .example + .example {
        margin-top: 4px;
      }

      .example.is-open {
        background: #fff;
        box-shadow: inset 0 0 0 1px rgba(223, 230, 241, 0.8);
      }

      .question-button {
        appearance: none;
        width: 100%;
        border: 0;
        background: transparent;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 20px;
        padding: 22px 22px;
        cursor: pointer;
        color: var(--text);
        font: inherit;
        text-align: left;
        font-weight: 780;
        letter-spacing: -0.015em;
      }

      .question-button:focus-visible {
        outline: 3px solid rgba(108, 92, 231, 0.28);
        outline-offset: -3px;
      }

      .question-button::after {
        content: "+";
        display: grid;
        flex: 0 0 auto;
        place-items: center;
        width: 32px;
        height: 32px;
        border-radius: 50%;
        color: #fff;
        background: var(--brand);
        font-size: 1.35rem;
        line-height: 1;
        transition: transform 180ms ease, background 180ms ease;
      }

      .question-button[aria-expanded="true"]::after {
        content: "−";
        transform: rotate(180deg);
        background: var(--brand-strong);
      }

      .details {
        padding: 0 22px 24px;
      }

      .answer {
        margin: 0;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.75;
      }

      @media (max-width: 840px) {
        .app-shell {
          padding: 40px 0;
        }

        .hero {
          grid-template-columns: 1fr;
        }

        .cat-card {
          min-height: 260px;
        }
      }

      @media (max-width: 560px) {
        .faq-toolbar,
        .question-button {
          padding: 18px;
        }

        .faq-toolbar {
          display: block;
        }

        .pill {
          display: inline-flex;
          margin-top: 16px;
        }

        .stats {
          grid-template-columns: 1fr;
        }

        .cat-card {
          min-height: 380px;
        }
      }
    </style>
  </head>
  <body>
    <main id="root"></main>

    <script>
      const faqs = [
        {
          question: "Why do cats knead blankets, pillows, or people?",
          answer:
            "Kneading is a comforting behavior that starts in kittenhood when cats press their paws against their mother while nursing. Adult cats often knead when they feel safe, relaxed, or ready to settle in."
        },
        {
          question: "How much sleep does a healthy cat need?",
          answer:
            "Most cats sleep between 12 and 16 hours a day, and kittens or senior cats may sleep even more. Short bursts of activity between naps are normal because cats are naturally crepuscular, meaning they are often most active around dawn and dusk."
        },
        {
          question: "Why does my cat bring toys or small gifts to me?",
          answer:
            "Cats may bring objects as a form of play, bonding, or instinctive hunting practice. Responding calmly and offering interactive toys can help redirect that energy in a positive way."
        },
        {
          question: "Do indoor cats need enrichment?",
          answer:
            "Yes. Indoor cats benefit from climbing spaces, scratching posts, puzzle feeders, window perches, and daily play. Enrichment helps prevent boredom and supports healthy movement, confidence, and problem solving."
        },
        {
          question: "How often should I groom my cat?",
          answer:
            "Short-haired cats usually need weekly brushing, while long-haired cats may need brushing several times a week. Regular grooming reduces shedding, prevents mats, and gives you a chance to notice skin changes early."
        },
        {
          question: "What does slow blinking mean?",
          answer:
            "A slow blink is often a sign of trust and relaxation. You can slowly blink back to communicate calmly, especially with a cat that is still getting comfortable around you."
        }
      ];

      function Header() {
        return `
          <section class="hero" aria-labelledby="page-title">
            <div>
              <p class="eyebrow">Cat care essentials</p>
              <h1 id="page-title">Frequently asked questions about cats.</h1>
              <p class="intro">
                Quick, practical answers for curious cat people. Expand any question to learn more about feline habits, care, and communication.
              </p>
            </div>
            <aside class="cat-card" aria-label="Cat care highlights">
              <div class="cat-illustration" aria-hidden="true">🐈</div>
              <div class="stats">
                <div class="stat"><strong>12–16h</strong><span>Daily sleep</span></div>
                <div class="stat"><strong>2x</strong><span>Play sessions</span></div>
                <div class="stat"><strong>7+</strong><span>Enrichment ideas</span></div>
              </div>
            </aside>
          </section>
        `;
      }

      function FAQItem({ question, answer }, index) {
        const panelId = `cat-faq-answer-${index + 1}`;
        const buttonId = `cat-faq-question-${index + 1}`;

        return `
          <div class="example">
            <button
              class="question-button"
              id="${buttonId}"
              type="button"
              aria-expanded="false"
              aria-controls="${panelId}"
            >
              ${question}
            </button>
            <div class="details" id="${panelId}" role="region" aria-labelledby="${buttonId}" hidden>
              <p class="answer">${answer}</p>
            </div>
          </div>
        `;
      }

      function FAQList(items) {
        return `
          <section class="faq-panel" aria-labelledby="faq-title">
            <div class="faq-toolbar">
              <div>
                <h2 id="faq-title">Cat FAQ</h2>
                <p>Questions are collapsed by default. Tap or click to expand.</p>
              </div>
              <span class="pill">${items.length} questions</span>
            </div>
            <div class="faq-list">
              ${items.map((item, index) => FAQItem(item, index)).join("")}
            </div>
          </section>
        `;
      }

      function App() {
        return `
          <div class="app-shell">
            ${Header()}
            ${FAQList(faqs)}
          </div>
        `;
      }

      document.querySelector("#root").innerHTML = App();

      document.querySelectorAll(".question-button").forEach((button) => {
        button.addEventListener("click", () => {
          const panel = document.getElementById(button.getAttribute("aria-controls"));
          const isExpanded = button.getAttribute("aria-expanded") === "true";

          button.setAttribute("aria-expanded", String(!isExpanded));
          button.closest(".example").classList.toggle("is-open", !isExpanded);
          panel.hidden = isExpanded;
        });
      });
    </script>
  </body>
</html>
